    try {
        const res = await fetch(`${API_BASE}/project/${projectId}/objects/${relationId}/cost`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                relation_id: relationId,
                item_name: itemName,
                quantity: qty,
                unit: unit,
                unit_price: price,
                duration_days: 1,
            }),
        });

        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
